/* Native image links work without this progressive enhancement. */
(()=>{'use strict';let dialog,viewer,title,fit,previous,loading;
function close(){if(!dialog?.open)return;dialog.close();viewer.removeAttribute('src');previous?.focus();}
function create(){dialog=document.createElement('dialog');dialog.className='image-reader';dialog.setAttribute('aria-labelledby','image-reader-title');dialog.innerHTML='<div class="image-reader-bar"><h2 class="image-reader-title" id="image-reader-title"></h2><button type="button" data-reader-fit>화면에 맞추기</button><button type="button" data-reader-close>닫기</button></div><p class="image-reader-note">원래 크기로 표시합니다. 작은 글씨는 좌우·아래로 이동해 읽을 수 있습니다.</p><p class="image-reader-loading" role="status">이미지 불러오는 중…</p><div class="image-reader-scroll" tabindex="0" aria-label="확대한 이미지 스크롤 영역"><img alt=""></div>';document.body.append(dialog);viewer=dialog.querySelector('img');title=dialog.querySelector('h2');fit=dialog.querySelector('[data-reader-fit]');loading=dialog.querySelector('[role=status]');dialog.querySelector('[data-reader-close]').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog)close();});fit.addEventListener('click',()=>{const fitted=dialog.dataset.fit==='true';dialog.dataset.fit=String(!fitted);fit.textContent=fitted?'화면에 맞추기':'원래 크기로 보기';});viewer.addEventListener('load',()=>{loading.hidden=true;});viewer.addEventListener('error',()=>{loading.hidden=false;loading.textContent='이미지를 불러오지 못했습니다. 닫은 뒤 이미지 링크로 다시 확인해 주세요.';});}
document.addEventListener('click',e=>{const link=e.target.closest?.('a[data-image-zoom]');if(!link||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||typeof HTMLDialogElement==='undefined')return;const source=link.getAttribute('href');if(!source)return;e.preventDefault();if(!dialog)create();previous=link;const image=link.querySelector('img');title.textContent=image?.alt||'이미지 확대';viewer.alt=title.textContent;dialog.dataset.fit='false';fit.textContent='화면에 맞추기';loading.hidden=false;loading.textContent='이미지 불러오는 중…';viewer.src=source;dialog.showModal();const region=dialog.querySelector('.image-reader-scroll');region.scrollTop=0;region.scrollLeft=0;});})();
